import { z } from 'zod'
import type { MasterConfig, MasterRow } from '../types'
import { countLabel } from './labels'

export type TeacherCategory = MasterRow & {
  slug: string
  description: string | null
  iconFileId: string | null
  iconUrl: string | null
  sortOrder: number
  teacherCount: number
  childPreferenceCount: number
}

// Mirrors the API rules in modules/M15 section 5. A blank description is sent as null. The slug is generated by the
// API and the icon needs an admin file upload, which does not exist yet, so neither is a form field.
export const teacherCategoryFormSchema = z.object({
  name: z.string().trim().min(2, 'Name must be 2–50 characters.').max(50, 'Name must be 2–50 characters.'),
  description: z.string().trim().max(200, 'Description can be up to 200 characters.'),
  sortOrder: z
    .number({ error: 'Order must be a number.' })
    .int('Order must be a whole number.')
    .min(0, 'Order must be 0–9,999.')
    .max(9999, 'Order must be 0–9,999.'),
  isActive: z.boolean(),
})
export type TeacherCategoryForm = z.infer<typeof teacherCategoryFormSchema>

export const teacherCategoriesConfig: MasterConfig<TeacherCategory, TeacherCategoryForm> = {
  key: 'teacher-categories',
  singular: 'teacher category',
  plural: 'teacher categories',
  title: 'Teacher categories',
  description: 'The teacher types parents browse by, shown as the category grid on the app home screen and used for each child’s preferences.',
  apiPath: '/teacher-categories',
  readPermission: 'education_masters.read',
  managePermission: 'education_masters.manage',
  searchPlaceholder: 'Search by name',
  fields: [
    { name: 'name', label: 'Name', kind: 'text', placeholder: 'Sports Coach', maxLength: 50 },
    { name: 'description', label: 'Description', kind: 'textarea', placeholder: 'Cricket, football, swimming and fitness coaches', maxLength: 200, hint: 'Shown on the category page (optional)' },
    { name: 'sortOrder', label: 'Order', kind: 'number', hint: 'Lower numbers come first; the first 8 active categories fill the home grid (0–9,999)' },
    { name: 'isActive', label: 'Active', kind: 'switch', hint: 'Inactive categories are hidden from filters and sign-up choices' },
  ],
  schema: teacherCategoryFormSchema,
  defaultValues: { name: '', description: '', sortOrder: 0, isActive: true },
  toFormValues: (c) => ({ name: c.name, description: c.description ?? '', sortOrder: c.sortOrder, isActive: c.isActive }),
  toPayload: (v) => ({
    name: v.name.trim(),
    description: v.description.trim() === '' ? null : v.description.trim(),
    sortOrder: v.sortOrder,
    isActive: v.isActive,
  }),
  columns: [
    {
      id: 'name',
      header: 'Category',
      sortKey: 'name',
      cell: (c) => (
        <span className="flex items-center gap-3">
          {c.iconUrl ? (
            <img src={c.iconUrl} alt="" className="h-7 w-7 rounded-md object-cover" />
          ) : (
            <span aria-hidden="true" className="flex h-7 w-7 items-center justify-center rounded-md bg-[var(--color-accent-soft)] text-xs font-semibold text-[var(--color-accent)]">
              {c.name.charAt(0).toUpperCase()}
            </span>
          )}
          <span className="font-medium">{c.name}</span>
        </span>
      ),
    },
    { id: 'slug', header: 'Slug', cell: (c) => <span className="font-mono text-xs">{c.slug}</span> },
    { id: 'description', header: 'Description', cell: (c) => <span className="line-clamp-1 max-w-xs text-[var(--color-fg-muted)]">{c.description ?? '—'}</span> },
    { id: 'order', header: 'Order', sortKey: 'sortOrder', align: 'right', cell: (c) => c.sortOrder },
  ],
  usage: (c) => {
    const parts = [c.teacherCount > 0 ? countLabel(c.teacherCount, 'teacher') : null, c.childPreferenceCount > 0 ? countLabel(c.childPreferenceCount, 'preference') : null].filter(Boolean)
    return { count: c.teacherCount + c.childPreferenceCount, label: parts.length > 0 ? parts.join(' · ') : 'Unused' }
  },
  referenceNames: { teachers: 'teachers', parent_child_teacher_categories: 'child preferences' },
  reorder: { sort: 'sortOrder', warning: 'The first 8 active categories fill the category grid on the app home screen.' },
  // FR-15.S2: show how many teachers are affected before a category they use is switched off.
  confirmDeactivate: (c) =>
    c.teacherCount > 0
      ? `${countLabel(c.teacherCount, 'teacher')} ${c.teacherCount === 1 ? 'uses' : 'use'} ${c.name}. It stays on their profiles, but disappears from filters and sign-up choices.`
      : null,
}
